import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

function expectCells(actual: [number, number][], expected: [number, number][]): void {
  expect(actual.sort((a, b) => a[0] - b[0] || a[1] - b[1])).toEqual(
    expected.sort((a, b) => a[0] - b[0] || a[1] - b[1]),
  );
}

describe("Game of Life", () => {
  it.todo("should return empty array for empty input -- []");
  it.todo(
    "should kill single live cell with no neighbors (underpopulation) -- [(0,0)] becomes []",
  );
  it.todo(
    "should kill live cells with fewer than 2 neighbors (underpopulation) -- [(0,1), (1,1)] becomes []",
  );
  it.todo(
    "should keep live cell with 2 or 3 neighbors (survival) -- center (1,1) survives in horizontal bar",
  );
  it.todo(
    "should kill live cell with more than 3 neighbors (overpopulation) -- center (1,1) dies in plus pattern",
  );
  it.todo(
    "should birth dead cell with exactly 3 live neighbors (reproduction) -- (1,1) becomes alive",
  );
  it.todo(
    "should leave block pattern unchanged (still life) -- [(0,0), (1,0), (0,1), (1,1)] unchanged",
  );
  it.todo(
    "should oscillate blinker horizontally (gen 0 to gen 1) -- [(0,0), (0,1), (0,2)] becomes [(-1,1), (0,1), (1,1)]",
  );
  it.todo(
    "should oscillate blinker back vertically (gen 1 to gen 2) -- [(-1,1), (0,1), (1,1)] becomes [(0,0), (0,1), (0,2)]",
  );
});

